let schoolExerciseTrigger=null;
function schoolExerciseStorageKey(id){return 'goc-hoc-tap.school-exercise.v1.'+id;}
function readSchoolExerciseDraft(id){try{return JSON.parse(localStorage.getItem(schoolExerciseStorageKey(id))||'{}')||{};}catch{return {};}}
function saveSchoolExerciseDraft(dialog){
 const inputs=[...dialog.querySelectorAll('[data-school-blank]')],choices=[...dialog.querySelectorAll('[data-school-choice]')];
 const draft={blanks:inputs.map(el=>el.value),choices:choices.map(el=>el.checked)};
 try{localStorage.setItem(schoolExerciseStorageKey(dialog.dataset.lessonId),JSON.stringify(draft));dialog.querySelector('[data-school-save-status]').textContent='Đã lưu bài làm trên thiết bị này.';}catch{dialog.querySelector('[data-school-save-status]').textContent='Trình duyệt chưa lưu được bài làm. Hãy giữ cửa sổ này để tiếp tục.';}
 return draft;
}
function openSchoolExercises(id){
 const report=schoolReports.find(r=>String(r.grade)===state.grade&&r.entries.some(e=>e.id===id)),entry=report?.entries.find(e=>e.id===id);
 if(!entry||state.program!=='Báo bài của trường'||entry.subject!==state.subject)return;
 const worksheet=schoolExerciseWorksheets[id];
 if(!worksheet){const notice=document.getElementById(id+'-exercises-notice');if(notice){notice.textContent='Bài học này chưa có bài tập. Đang chờ bổ sung.';notice.hidden=false;}return;}
 let dialog=document.querySelector('#school-exercise-dialog');
 if(!dialog){dialog=document.createElement('dialog');dialog.id='school-exercise-dialog';dialog.className='school-exercise-dialog';dialog.setAttribute('aria-labelledby','school-exercise-title');document.body.append(dialog);
  dialog.addEventListener('close',()=>{if(schoolExerciseTrigger?.isConnected)schoolExerciseTrigger.focus({preventScroll:true});saveCurrentView();});
  dialog.addEventListener('input',()=>saveSchoolExerciseDraft(dialog));
  dialog.addEventListener('scroll',()=>saveCurrentView(),{passive:true});
  dialog.addEventListener('click',e=>{if(e.target.closest('[data-school-exercise-close]'))dialog.close();if(e.target.closest('[data-school-exercise-save]'))saveSchoolExerciseDraft(dialog);});
 }
 schoolExerciseTrigger=document.querySelector(`[data-school-exercises="${id}"]`)||document.activeElement;
 const art=(index,label)=>`<span class="school-worksheet-art school-worksheet-art-${index}" role="img" aria-label="${label}"></span>`;
 const draft=readSchoolExerciseDraft(id),table=(rows,label)=>`<table aria-label="${label}"><tbody>${rows.map(row=>`<tr>${row.map(word=>`<td>${escapeHTML(word)}</td>`).join('')}</tr>`).join('')}</tbody></table>`;
 dialog.innerHTML=`<header><div><p>Làm bài tập · Tiếng việt · Lớp 1</p><h2 id="school-exercise-title">${escapeHTML(entry.title)}</h2></div><button type="button" data-school-exercise-close aria-label="Đóng bài tập">×</button></header><div class="school-exercise-paper"><section aria-labelledby="school-reading-title"><h3 id="school-reading-title"><span>1</span> Luyện đọc <small>(Nhờ phụ huynh giúp con luyện đọc nhiều lần)</small></h3><p class="school-sounds">${worksheet.sounds.map(word=>`<span>${word}</span>`).join('')}</p>${table(worksheet.words,'Luyện đọc từ')}${table(worksheet.phrases,'Luyện đọc cụm từ')}${worksheet.reading.map(line=>`<p class="school-reading-line">${escapeHTML(line)}</p>`).join('')}</section><section aria-labelledby="school-blanks-title"><h3 id="school-blanks-title"><span>2</span> Điền vào chỗ trống: <em>ai/ay</em></h3><div class="school-blanks">${worksheet.blanks.map(([before,after],i)=>`<div class="school-blank-item">${art(i,['Những bàn tay giơ lên','Máy bay đồ chơi','Máy sấy màu hồng','Gà mái trong ổ'][i])}<label><span>${escapeHTML(before)}</span><input data-school-blank="${i}" aria-label="Điền ai hoặc ay, câu ${i+1}: ${escapeHTML(before)}…${escapeHTML(after)}" type="text" maxlength="20" autocomplete="off" spellcheck="false" value="${escapeHTML(typeof draft.blanks?.[i]==='string'?draft.blanks[i].slice(0,20):'')}"><span>${escapeHTML(after)}</span></label></div>`).join('')}</div></section><section aria-labelledby="school-choices-title"><h3 id="school-choices-title"><span>3</span> Đánh dấu ✓ vào câu phù hợp với hình:</h3><div class="school-picture-choices">${worksheet.choices.map((rows,group)=>`<fieldset><legend>Hình ${group+1}</legend>${art(group+4,group===0?'Hai bạn nhỏ với dây nhảy':'Hai bạn nhỏ ngồi trên đu quay có các ghế hình máy bay')}${rows.map((text,i)=>`<label><input type="checkbox" data-school-choice="${group*2+i}" ${draft.choices?.[group*2+i]===true?'checked':''}><span>${escapeHTML(text)}</span></label>`).join('')}</fieldset>`).join('')}</div></section><footer><p>Chờ đáp án do phụ huynh cung cấp.</p><button type="button" data-school-exercise-save>Lưu bài làm</button><p data-school-save-status role="status">Bài làm được lưu trên trình duyệt này.</p></footer></div>`;
 dialog.dataset.lessonId=id;dialog.showModal();saveCurrentView();
}
